SELECT p.gender, p.anchor_age, d.icd_code, COUNT(*)::FLOAT / (SELECT COUNT(*) FROM admissions a JOIN patients pt ON a.subject_id = pt.subject_id JOIN diagnoses_icd dc ON a.subject_id = dc.subject_id WHERE pt.gender = p.gender AND pt.anchor_age BETWEEN 61 AND 71 AND dc.icd_code = d.icd_code) AS proportion FROM admissions a JOIN patients pt ON a.subject_id = pt.subject_id JOIN diagnoses_icd dc ON a.subject_id = dc.subject_id JOIN d_icd_diagnoses d ON dc.icd_code = d.icd_code WHERE pt.gender = p.gender AND pt.anchor_age BETWEEN 61 AND 71 AND dc.icd_code = d.icd_code GROUP BY p.gender, p.anchor_age, d.icd_code ORDER BY p.gender, p.anchor_age, d.icd_code NULLS LAST;